create extension if not exists "pgcrypto";
create table if not exists clientes (id uuid primary key references auth.users(id) on delete cascade, nombre text not null default '', telefono text, direccion text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists mascotas (id uuid primary key default gen_random_uuid(), cliente_id uuid not null references clientes(id) on delete cascade, nombre text not null, especie text, raza text, sexo text, fecha_nacimiento date, fotografia_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists servicios (id uuid primary key default gen_random_uuid(), nombre text not null, descripcion text, activo boolean not null default true, created_at timestamptz not null default now());
create table if not exists citas (id uuid primary key default gen_random_uuid(), cliente_id uuid not null references clientes(id) on delete cascade, mascota_id uuid not null references mascotas(id), servicio_id uuid references servicios(id), fecha_hora timestamptz not null, motivo text not null check (length(trim(motivo)) > 0), estado text not null default 'Pendiente' check (estado in ('Pendiente','Confirmada','Reprogramada','Atendida','Cancelada')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists vacunas (id uuid primary key default gen_random_uuid(), mascota_id uuid not null references mascotas(id) on delete cascade, nombre text not null, fecha_aplicacion date, proxima_dosis date, estado text, lote text, created_at timestamptz not null default now());
create table if not exists historiales_clinicos (id uuid primary key default gen_random_uuid(), mascota_id uuid not null references mascotas(id) on delete cascade, fecha date not null default current_date, motivo text, diagnostico text, tratamiento text, receta text, indicaciones text, examenes text, proximo_control date, autorizado boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists notificaciones (id uuid primary key default gen_random_uuid(), cliente_id uuid not null references clientes(id) on delete cascade, titulo text not null, mensaje text not null, leida boolean not null default false, tipo text, created_at timestamptz not null default now());
create or replace function public.crear_cliente() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.clientes(id,nombre) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.crear_cliente();
do $$ declare t text; begin foreach t in array array['clientes','mascotas','servicios','citas','vacunas','historiales_clinicos','notificaciones'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy clientes_propios on clientes for all using (id=auth.uid()) with check (id=auth.uid());
create policy mascotas_propias on mascotas for select using (cliente_id=auth.uid());
create policy citas_propias on citas for select using (cliente_id=auth.uid()); create policy citas_crear_propias on citas for insert with check (cliente_id=auth.uid() and exists(select 1 from mascotas m where m.id=mascota_id and m.cliente_id=auth.uid())); create policy citas_cancelar_propias on citas for update using (cliente_id=auth.uid()) with check (cliente_id=auth.uid());
create policy servicios_publicos on servicios for select using (activo=true);
create policy vacunas_propias on vacunas for select using (exists(select 1 from mascotas m where m.id=mascota_id and m.cliente_id=auth.uid()));
create policy historial_autorizado on historiales_clinicos for select using (autorizado and exists(select 1 from mascotas m where m.id=mascota_id and m.cliente_id=auth.uid()));
create policy notificaciones_propias on notificaciones for select using (cliente_id=auth.uid()); create policy notificaciones_leer on notificaciones for update using (cliente_id=auth.uid()) with check (cliente_id=auth.uid());
